pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 blkTimestamp, uint256 blkNumber, uint256 actorSeed) public {
        // bound the admissible domain: any amount, valid timestamp and block number
        bound(amount, 0, 100 ether);
        bound(blkTimestamp, 1, type(uint256).max);
        bound(blkNumber, 0, type(uint256).max);

        // generate a distinct EOA address from the fuzzer seed
        address actor = address(uint160(uint256(keccak256(abi.encode(actorSeed)))));
        // exclude precompiles and zero address
        vm.assume(actor != address(0) && actor.code.length == 0 && actor != address(this));

        // set up block environment
        vm.warp(blkTimestamp);
        vm.roll(blkNumber);

        // fund the actor and attempt to call fallback with the fuzzed amount
        vm.deal(actor, amount);

        // record initial state: balance and pastBlockTime
        uint256 initBal = address(c).balance;
        uint256 initPast = c.pastBlockTime();

        bool success;
        vm.prank(actor);
        try c.f{value: amount}() {
            success = true;
        } catch {
            success = false;
        }

        // GENERAL RULE: if the call succeeds, the amount sent must be exactly 10 ether;
        // otherwise the reference would have reverted. The buggy version requires 20 ether,
        // so it reverts (does not accept) valid 10 ether payments, breaking the invariant
        // that success implies amount == 10 ether.
        assertTrue(!success || amount == 10 ether, "success implies exactly 10 ether");
    }
}

