        // 1. Restrict to admissible domain: timestamp strictly greater than pastBlockTime
        vm.assume(warpAmount > 0 && warpAmount < 1000);
        vm.warp(block.timestamp + warpAmount);

        // 2. Deploy an adversarial helper that always reverts on receive
        Reverter revertingCallee = new Reverter();
        vm.deal(caller, 10 ether);

        uint256 balanceBefore = address(c).balance;
        vm.prank(caller);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        uint256 balanceAfter = address(c).balance;

        // 3. When msg.value == 10 ether and the call succeeds (reference behavior),
