        uint256 newPastBlockTime = c.pastBlockTime();

        // Invariant: pastBlockTime after second call must be strictly greater than after first call.
        // Reference: warp1+1 < warp2+1 always holds; Mutant: warp2 can be equal to oldPastBlockTime if warp2 = warp1+something.
        assertTrue(newPastBlockTime > oldPastBlockTime);
    }
