pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        // Use seed to derive a sequence of up to 16 calls to explore state space.
        uint256 calls = (seed % 16) + 1;
        uint256 expectedBalance = 0;
        uint256 lastTimestamp = block.timestamp + 1000; // ensure first call passes require(block.timestamp > pastBlockTime)
        uint256 lastBlock = block.number + 1;

        // We will simulate a sequence of external fallback calls, each with 10 ether.
        // The caller needs enough ether; we use a dedicated caller address.
        address caller = address(0x1234);
        vm.deal(caller, 1000 ether);

        for (uint256 i = 0; i < calls; i++) {
            // Advance block.timestamp and block.number randomly based on seed.
            uint256 advanceTime = uint256(keccak256(abi.encode(seed, i, 0))) % 100 + 1;
            uint256 advanceBlock = uint256(keccak256(abi.encode(seed, i, 1))) % 100 + 1;
            vm.warp(block.timestamp + advanceTime);
            vm.roll(block.number + advanceBlock);

            // Try to call fallback with 10 ether from the caller.
            vm.prank(caller);
            (bool ok, ) = address(c).call{value: 10 ether}("");

            // If call succeeded, update expected balance.
            if (ok) {
                expectedBalance += 10 ether;
                // If the call triggered the transfer (block.number % 15 == 0),
                // the contract's balance is zeroed out. We need to reflect that.
                if (block.number % 15 == 0) {
                    expectedBalance = 0;
                }
            }
        }

        // The invariant: after the sequence, the contract's actual balance
        // must equal our tracked expected balance.
        assertTrue(address(c).balance == expectedBalance);
    }
}

